"""Assay-guided electrolyte batch design.

Deterministic active policy:
  * query a small set of proxy/temperature leaders;
  * fit residual corrections in log-conductivity space;
  * spend remaining assays adaptively on candidates with high corrected promise and
    useful formulation-space exploration;
  * choose the best three-formulation batch for the supplied duty profile with the
    visible objective's dominant conductivity term and a modest diversity term.
"""

import itertools
import math
from collections.abc import Mapping, Sequence

import numpy as np


def _as_float_array(x):
    try:
        a = np.asarray(x, dtype=float)
    except Exception:
        return None
    if a.ndim == 0 or not np.all(np.isfinite(a)):
        return None
    return a


def _extract_numeric_arrays(obj, ntemp, path=""):
    found = []
    if isinstance(obj, Mapping):
        for k, v in obj.items():
            keypath = (path + "/" + str(k)).lower()
            arr = _as_float_array(v)
            if arr is not None:
                if arr.ndim == 1 and arr.size == ntemp:
                    found.append((keypath, arr.astype(float)))
                elif arr.ndim == 2 and ntemp in arr.shape:
                    if arr.shape[1] == ntemp:
                        for i in range(arr.shape[0]):
                            found.append((keypath, arr[i].astype(float)))
                    elif arr.shape[0] == ntemp:
                        for i in range(arr.shape[1]):
                            found.append((keypath, arr[:, i].astype(float)))
            found.extend(_extract_numeric_arrays(v, ntemp, keypath))
    elif isinstance(obj, Sequence) and not isinstance(obj, (str, bytes, bytearray)):
        arr = _as_float_array(obj)
        if arr is not None:
            if arr.ndim == 1 and arr.size == ntemp:
                found.append((path.lower(), arr.astype(float)))
            elif arr.ndim == 2 and ntemp in arr.shape:
                if arr.shape[1] == ntemp:
                    for i in range(arr.shape[0]):
                        found.append((path.lower(), arr[i].astype(float)))
                elif arr.shape[0] == ntemp:
                    for i in range(arr.shape[1]):
                        found.append((path.lower(), arr[:, i].astype(float)))
        else:
            for i, v in enumerate(obj):
                found.extend(_extract_numeric_arrays(v, ntemp, path + "/" + str(i)))
    return found


def _conductivity_from_assay(result, ntemp):
    arrays = []
    for key, arr in _extract_numeric_arrays(result, ntemp):
        lk = key.lower()
        if "conduct" not in lk and "sigma" not in lk:
            continue
        if np.any(arr <= 0.0):
            continue
        if any(s in lk for s in ("uncert", "quality", "r2", "rmse", "error", "residual", "fit")):
            continue
        arrays.append((lk, arr))

    if not arrays:
        return None, None

    preferred = [
        arr
        for key, arr in arrays
        if ("mean" in key or "average" in key or "avg" in key)
        and "min" not in key
        and "max" not in key
        and "lower" not in key
        and "upper" not in key
    ]
    if preferred:
        mean_scan = np.mean(np.vstack(preferred), axis=0)
    else:
        indiv = [
            arr
            for key, arr in arrays
            if "min" not in key and "max" not in key and "lower" not in key and "upper" not in key
        ]
        if not indiv:
            indiv = [arr for _, arr in arrays]
        mean_scan = np.mean(np.vstack(indiv), axis=0)

    conservative = [arr for key, arr in arrays if "min" in key or "lower" in key or "worst" in key]
    if conservative:
        robust_scan = np.mean(np.vstack(conservative), axis=0)
    else:
        indiv = [
            arr
            for key, arr in arrays
            if "max" not in key
            and "upper" not in key
            and "mean" not in key
            and "avg" not in key
            and "average" not in key
        ]
        robust_scan = np.min(np.vstack(indiv), axis=0) if len(indiv) >= 2 else mean_scan

    return np.maximum(mean_scan, 1e-12), np.maximum(robust_scan, 1e-12)


def _numeric_features(row):
    vals = []
    ratios = row.get("ratios", {})
    if isinstance(ratios, Mapping):
        for k in sorted(ratios):
            try:
                vals.append(float(ratios[k]))
            except Exception:
                pass

    for k in sorted(row):
        if k in ("id", "ratios", "proxy_conductivity_s_cm"):
            continue
        v = row[k]
        if isinstance(v, (int, float, np.number)):
            vals.append(float(v))
        elif isinstance(v, Mapping):
            for kk in sorted(v):
                vv = v[kk]
                if isinstance(vv, (int, float, np.number)):
                    vals.append(float(vv))
    return vals


def _feature_matrix(rows):
    raw = [_numeric_features(r) for r in rows]
    m = max((len(x) for x in raw), default=0)
    if m == 0:
        return np.zeros((len(rows), 0), dtype=float)
    x = np.zeros((len(rows), m), dtype=float)
    for i, vals in enumerate(raw):
        x[i, : len(vals)] = vals
    return x


def _diversity_values(rows):
    values = []
    for row in rows:
        ratios = row.get("ratios", {})
        values.append(
            (
                float(ratios.get("pc_in_cyclic_carbonates", 0.0)),
                float(ratios.get("salt_to_cyclic_carbonates", 0.0)),
            )
        )
    values = np.asarray(values, dtype=float)
    spans = np.ptp(values, axis=0)
    spans[spans <= 0.0] = 1.0
    return values, spans


def _diversity_of_indices(values, spans, indices):
    ds = [
        np.mean(np.abs((values[i] - values[j]) / spans))
        for i, j in itertools.combinations(indices, 2)
    ]
    return float(np.mean(ds)) if ds else 0.0


def _initial_assays(rows, proxy_logs, weights, budget):
    n = len(rows)
    q = proxy_logs @ weights
    chosen = []

    def add(i):
        if 0 <= i < n and i not in chosen and len(chosen) < budget:
            chosen.append(int(i))

    add(int(np.argmax(q)))

    # Temperature leaders are valuable because the January campaigns can shift
    # high-temperature optima relative to the historical proxy.
    for t in np.argsort(-weights):
        add(int(np.argmax(proxy_logs[:, t])))
        if len(chosen) >= min(4, budget):
            break

    for i in np.argsort(-q):
        add(int(i))
        if len(chosen) >= min(5, budget):
            break

    return chosen


def _ridge_residual_predict(features, proxy_logs, observed):
    n, _ = proxy_logs.shape
    pred = np.array(proxy_logs, copy=True)
    if not observed:
        return pred

    obs_idx = np.asarray(sorted(observed), dtype=int)
    y_obs = np.vstack([observed[int(i)] for i in obs_idx])
    residual = y_obs - proxy_logs[obs_idx]
    pred[obs_idx] = y_obs

    if len(obs_idx) < 3 or features.shape[1] == 0:
        mean_resid = np.mean(residual, axis=0)
        for i in range(n):
            if i not in observed:
                pred[i] = proxy_logs[i] + 0.40 * mean_resid
        return pred

    x = np.asarray(features, dtype=float)
    mu = np.mean(x[obs_idx], axis=0)
    sd = np.std(x[obs_idx], axis=0)
    sd[sd < 1e-12] = 1.0
    xs = (x - mu) / sd

    # Intercept, linear, squared terms and a compact salt/solvent interaction when
    # available.  This is still strongly regularized for eight or fewer assays.
    parts = [np.ones((n, 1)), xs, xs * xs]
    if xs.shape[1] >= 2:
        parts.append((xs[:, :1] * xs[:, 1:2]))
    phi = np.concatenate(parts, axis=1)

    po = phi[obs_idx]
    lam = 0.85 + 0.12 * phi.shape[1]
    a = po.T @ po + lam * np.eye(po.shape[1])
    b = po.T @ residual
    try:
        coef = np.linalg.solve(a, b)
        resid_pred = phi @ coef
    except np.linalg.LinAlgError:
        resid_pred = np.tile(np.mean(residual, axis=0), (n, 1))

    center = np.mean(xs[obs_idx], axis=0)
    dist = np.sqrt(np.mean((xs - center) ** 2, axis=1))
    shrink = 0.72 / (1.0 + 0.30 * dist)
    for i in range(n):
        if i not in observed:
            pred[i] = proxy_logs[i] + shrink[i] * resid_pred[i]
    pred[obs_idx] = y_obs
    return pred


def _adaptive_next(features, proxy_logs, weights, rows, observed, values, spans):
    n = len(rows)
    pred = _ridge_residual_predict(features, proxy_logs, observed)
    q = pred @ weights
    qn = (q - np.min(q)) / (np.ptp(q) + 1e-12)

    if observed:
        obs = list(observed)
        x = features
        if x.shape[1] == 0:
            novelty = np.ones(n)
        else:
            mu = np.mean(x[obs], axis=0)
            sd = np.std(x[obs], axis=0)
            sd[sd < 1e-12] = 1.0
            xs = (x - mu) / sd
            novelty = np.array([min(np.sqrt(np.mean((xs[i] - xs[j]) ** 2)) for j in obs) for i in range(n)])
            novelty = novelty / (np.max(novelty) + 1e-12)
        div_to_obs = np.array(
            [
                min(float(np.mean(np.abs((values[i] - values[j]) / spans))) for j in obs)
                for i in range(n)
            ]
        )
        div_to_obs = div_to_obs / (np.max(div_to_obs) + 1e-12)
    else:
        novelty = np.ones(n)
        div_to_obs = np.ones(n)

    best = None
    for i in range(n):
        if i in observed:
            continue
        # Mostly exploit corrected predicted quality; keep some exploration to
        # protect against proxy false promotions and residual extrapolation.
        score = 0.78 * qn[i] + 0.13 * novelty[i] + 0.09 * div_to_obs[i]
        if best is None or score > best[0] + 1e-15 or (
            math.isclose(score, best[0], abs_tol=1e-15) and i < best[1]
        ):
            best = (float(score), i)
    return best[1]


def design_electrolyte_batch(problem, assay):
    rows = list(problem["candidate_formulations"])
    n = len(rows)
    batch_size = int(problem.get("batch_size", 3))
    budget = min(int(problem.get("assay_budget", 8)), n)

    weights = np.asarray(problem["application_weights"], dtype=float)
    weights = weights / (np.sum(weights) + 1e-300)

    proxy = np.asarray([row["proxy_conductivity_s_cm"] for row in rows], dtype=float)
    proxy = np.maximum(proxy, 1e-12)
    proxy_logs = np.log(proxy)
    ntemp = proxy_logs.shape[1]

    features = _feature_matrix(rows)
    values, spans = _diversity_values(rows)

    observed_logs = {}
    robust_logs = {}

    initial = _initial_assays(rows, proxy_logs, weights, budget)
    assay_order = []
    for idx in initial:
        if len(assay_order) < budget and idx not in assay_order:
            assay_order.append(idx)

    # Query initial set, then choose remaining assays adaptively from corrected model.
    k = 0
    while len(observed_logs) < budget:
        if k < len(assay_order):
            idx = assay_order[k]
            k += 1
            if idx in observed_logs:
                continue
        else:
            idx = _adaptive_next(features, proxy_logs, weights, rows, observed_logs, values, spans)

        fid = rows[idx]["id"]
        result = assay(fid)
        mean_scan, robust_scan = _conductivity_from_assay(result, ntemp)
        if mean_scan is not None:
            observed_logs[idx] = np.log(mean_scan)
            robust_logs[idx] = np.log(robust_scan if robust_scan is not None else mean_scan)
        else:
            # Should not happen for valid evaluator output, but avoid re-querying.
            observed_logs[idx] = proxy_logs[idx]
            robust_logs[idx] = proxy_logs[idx]

    pred_logs = _ridge_residual_predict(features, proxy_logs, observed_logs)

    # Visible combined_score is primarily mean log-conductivity quality.  Use the
    # assayed mean scans exactly; retain only a very small conservative tie-break
    # effect through a separate penalty rather than depressing the main estimate.
    final_logs = np.array(pred_logs, copy=True)
    for idx, y in observed_logs.items():
        final_logs[idx] = y

    q = final_logs @ weights
    qn = (q - np.min(q)) / (np.ptp(q) + 1e-12)

    # Optional tiny repeat-risk penalty for assayed candidates with large downside.
    risk = np.zeros(n, dtype=float)
    for idx, r in robust_logs.items():
        risk[idx] = max(0.0, float((observed_logs[idx] @ weights) - (r @ weights)))

    best = None
    for inds in itertools.combinations(range(n), batch_size):
        inds_list = list(inds)
        div = _diversity_of_indices(values, spans, inds)
        val = 0.90 * float(np.mean(qn[inds_list])) + 0.10 * div
        val += 0.004 * sum(1 for i in inds if i in observed_logs) / float(batch_size)
        val -= 0.006 * float(np.mean(risk[inds_list]))
        ids = tuple(rows[i]["id"] for i in inds)
        if best is None or val > best[0] + 1e-15 or (
            math.isclose(val, best[0], abs_tol=1e-15) and ids < best[1]
        ):
            best = (float(val), ids)

    return {"formulation_ids": list(best[1])}

"""Deterministic scalar-blaze heuristic for the diffraction grating task.

The design is a multilayer binary approximation to a transmitted phase ramp.
Compared with the parent, this version evaluates several robust staircase
quantizations and phase depths with a simple thin-element Fourier model, then
returns the candidate with the largest predicted +1 coefficient while obeying
the public fabrication limits.
"""

import math
import numpy as np


def _as_float(x, default):
    try:
        v = float(x)
        if math.isfinite(v):
            return v
    except Exception:
        pass
    return float(default)


def _bounds(problem, names, default):
    for name in names:
        if name in problem:
            try:
                b = np.asarray(problem[name], dtype=float).ravel()
                if b.size >= 2 and np.all(np.isfinite(b[:2])):
                    lo, hi = float(b[0]), float(b[1])
                    if lo > hi:
                        lo, hi = hi, lo
                    return lo, hi
            except Exception:
                pass
    return float(default[0]), float(default[1])


def _first_number_from_keys(problem, key_fragments, default):
    key_fragments = tuple(s.lower() for s in key_fragments)
    for k, v in problem.items():
        lk = str(k).lower()
        if all(s in lk for s in key_fragments):
            try:
                arr = np.asarray(v, dtype=float).ravel()
                arr = arr[np.isfinite(arr)]
                if arr.size:
                    return float(np.mean(arr))
            except Exception:
                pass
    return float(default)


def _positive_array_from_keys(problem, keys):
    for key in keys:
        if key in problem:
            try:
                a = np.asarray(problem[key], dtype=float).ravel()
                a = a[np.isfinite(a)]
                a = a[a > 0]
                if a.size:
                    return a.astype(float)
            except Exception:
                pass
    return np.array([], dtype=float)


def _wavelengths_um(problem, period):
    a = _positive_array_from_keys(
        problem,
        (
            "wavelength_um",
            "lambda_um",
            "development_wavelength_um",
            "center_wavelength_um",
            "wavelengths_um",
            "lambda_grid_um",
            "development_wavelengths_um",
        ),
    )
    if a.size:
        return a
    return np.array([float(period)], dtype=float)


def _index_contrast(problem):
    highs = []
    lows = []
    for k, v in problem.items():
        lk = str(k).lower()
        if ("index" in lk) or lk.startswith("n_") or lk.endswith("_n") or ("refractive" in lk):
            try:
                a = np.asarray(v, dtype=float).ravel()
                a = a[np.isfinite(a)]
                a = a[(a > 0.8) & (a < 5.0)]
                if a.size:
                    val = float(np.median(a))
                    if any(s in lk for s in ("high", "ridge", "dielectric", "grating", "core")):
                        highs.append(val)
                    if any(s in lk for s in ("low", "void", "air", "ambient", "superstrate", "clad")):
                        lows.append(val)
            except Exception:
                pass

    if highs and lows:
        dn = max(highs) - min(lows)
        if math.isfinite(dn) and dn > 0.05:
            return float(dn)

    vals = []
    for k, v in problem.items():
        lk = str(k).lower()
        if ("index" in lk) or lk.startswith("n_") or lk.endswith("_n") or ("refractive" in lk):
            try:
                a = np.asarray(v, dtype=float).ravel()
                a = a[np.isfinite(a)]
                a = a[(a > 0.8) & (a < 5.0)]
                vals.extend(a.tolist())
            except Exception:
                pass
    if len(vals) >= 2:
        dn = max(vals) - min(vals)
        if dn > 0.05:
            return float(dn)

    return 0.55


def _total_depth_limit(problem, layer_count, depth_hi):
    total_hi = None
    for key in (
        "total_depth_um",
        "max_total_depth_um",
        "total_depth_limit_um",
        "total_depth_max_um",
        "max_depth_um",
    ):
        if key in problem:
            try:
                a = np.asarray(problem[key], dtype=float).ravel()
                a = a[np.isfinite(a)]
                if a.size:
                    val = float(np.max(a))
                    if val > 0:
                        total_hi = val if total_hi is None else min(total_hi, val)
            except Exception:
                pass
    if total_hi is None:
        total_hi = layer_count * depth_hi
    return float(min(total_hi, layer_count * depth_hi))


def _thin_score(depths, fills, offsets, wavelengths, dn, order):
    # Simple scalar transmitted-phase Fourier efficiency into the requested
    # order.  Sampled densely enough for deterministic candidate selection.
    n = 1024
    x = (np.arange(n, dtype=float) + 0.5) / n
    h = np.zeros(n, dtype=float)
    for d, f, o in zip(depths, fills, offsets):
        f = float(np.clip(f, 0.0, 1.0))
        if f <= 0.0 or d == 0.0:
            continue
        # Interpret offset as ridge center; periodic interval of width f.
        dist = (x - float(o) + 0.5) % 1.0 - 0.5
        h += float(d) * (np.abs(dist) <= 0.5 * f)
    carrier = np.exp(-1j * 2.0 * np.pi * int(order) * x)
    vals = []
    for wl in wavelengths:
        phi = 2.0 * np.pi * dn * h / max(float(wl), 1e-12)
        c = np.mean(np.exp(1j * phi) * carrier)
        vals.append(float(abs(c) ** 2))
    return float(np.mean(vals)) if vals else 0.0


def design_grating(problem):
    period = _as_float(problem.get("period_um", 1.0), 1.0)
    if period <= 0:
        period = 1.0

    layer_count = int(problem.get("layer_count", 5))
    if layer_count <= 0:
        layer_count = 5

    depth_lo, depth_hi = _bounds(
        problem,
        ("depth_bounds_um", "layer_depth_bounds_um", "depth_bounds", "etch_depth_bounds_um"),
        (0.0, 0.25 * period),
    )
    fill_lo, fill_hi = _bounds(
        problem,
        ("fill_bounds", "fill_fraction_bounds", "ridge_fill_fraction_bounds", "duty_cycle_bounds"),
        (0.0, 1.0),
    )
    off_lo, off_hi = _bounds(
        problem,
        ("offset_bounds", "offset_fraction_bounds", "lateral_offset_bounds"),
        (0.0, 1.0),
    )

    min_feature = _first_number_from_keys(problem, ("min", "feature"), 0.0)
    if min_feature > 0 and period > 0:
        mf = min(0.49, max(0.0, min_feature / period))
        fill_lo = max(fill_lo, mf)
        fill_hi = min(fill_hi, 1.0 - mf)

    fill_lo = max(0.0, fill_lo)
    fill_hi = min(1.0, fill_hi)
    if fill_lo > fill_hi:
        mid = min(1.0, max(0.0, 0.5 * (fill_lo + fill_hi)))
        fill_lo = fill_hi = mid

    off_lo = max(0.0, off_lo)
    off_hi = min(1.0, off_hi)
    if off_lo > off_hi:
        off_lo = off_hi = min(1.0, max(0.0, 0.5 * (off_lo + off_hi)))

    wavelengths = _wavelengths_um(problem, period)
    wl_med = float(np.median(wavelengths)) if wavelengths.size else float(period)
    dn = max(0.12, _index_contrast(problem))

    max_total = _total_depth_limit(problem, layer_count, depth_hi)
    min_total = max(0.0, layer_count * depth_lo)

    order = int(round(_as_float(problem.get("target_order", problem.get("order", 1)), 1)))
    if order == 0:
        order = 1

    # Practical fill interval.  Even with zero public minimum feature, avoid
    # vanishing slivers because they are fragile under sealed perturbations.
    soft_margin = min(0.075, max(0.0, 0.025 / max(period, 1e-9)))
    lo = max(fill_lo, soft_margin)
    hi = min(fill_hi, 1.0 - soft_margin)
    if lo > hi:
        lo, hi = fill_lo, fill_hi

    L = layer_count
    if L == 1:
        schemes = [np.array([0.5], dtype=float)]
    else:
        # Parent half-bin scheme, equal-bin staircase, and two mildly biased
        # variants.  Equal-bin thresholds give nearly uniform phase terraces for
        # a finite-level blaze, often improving scalar +1 efficiency.
        u_parent = (np.arange(L, dtype=float) + 0.5) / float(L)
        u_equal = (np.arange(1, L + 1, dtype=float)) / float(L + 1)
        u_sqrt = u_equal ** 0.88
        u_pow = u_equal ** 1.12
        schemes = [u_equal, u_parent, u_sqrt, u_pow]

    candidates = []
    for u in schemes:
        fills = lo + np.asarray(u, dtype=float) * (hi - lo)
        fills = np.clip(fills, fill_lo, fill_hi)

        # Right-edge registration blazes to +1 for the convention used by the
        # public parent; reverse if a negative target order is explicitly given.
        if order < 0:
            offsets = 0.5 * fills
        else:
            offsets = 1.0 - 0.5 * fills
        offsets = np.mod(offsets, 1.0)
        offsets = np.clip(offsets, off_lo, off_hi)

        # Several phase heights.  Finite-level scalar blaze prefers close to
        # one wave, while RCWA angular/polarization averaging is usually a bit
        # shallower, so include both and select by scalar multi-wavelength score.
        for phase_waves in (0.70, 0.76, 0.82, 0.88, 0.94, 1.00):
            target_total = phase_waves * wl_med / dn
            target_total = min(target_total, 1.15 * period)
            total = min(max(target_total, min_total), max_total)
            if not math.isfinite(total) or total <= 0:
                total = min(max_total, max(min_total, 0.1 * period))
            per_depth = min(max(total / L, depth_lo), depth_hi)
            depths = np.full(L, per_depth, dtype=float)

            # If per-layer clipping changed the sum below the allowed target and
            # lower-bound layers permit redistribution, top up greedily.
            remaining = min(total, max_total) - float(np.sum(depths))
            if remaining > 1e-15:
                for i in range(L):
                    add = min(remaining, depth_hi - depths[i])
                    if add > 0:
                        depths[i] += add
                        remaining -= add
                    if remaining <= 1e-15:
                        break

            candidates.append((depths, fills, offsets))

    best = None
    best_score = -1.0
    for depths, fills, offsets in candidates:
        sc = _thin_score(depths, fills, offsets, wavelengths, dn, order)
        # Tiny preference for less extreme depth if scalar scores tie, improving
        # tolerance to index and etch shifts.
        sc -= 1e-4 * (float(np.sum(depths)) / max(period, 1e-12))
        if sc > best_score:
            best_score = sc
            best = (depths, fills, offsets)

    if best is None:
        depths = np.full(layer_count, min(max(0.15 * period, depth_lo), depth_hi), dtype=float)
        fills = np.full(layer_count, min(max(0.5, fill_lo), fill_hi), dtype=float)
        offsets = np.full(layer_count, min(max(0.5, off_lo), off_hi), dtype=float)
    else:
        depths, fills, offsets = best

    design = np.zeros((layer_count, 3), dtype=float)
    design[:, 0] = depths
    design[:, 1] = fills
    design[:, 2] = offsets

    design = np.asarray(design, dtype=float)
    design[~np.isfinite(design)] = 0.0
    design[:, 0] = np.clip(design[:, 0], depth_lo, depth_hi)
    design[:, 1] = np.clip(design[:, 1], fill_lo, fill_hi)
    design[:, 2] = np.clip(design[:, 2], off_lo, off_hi)

    # Enforce total-depth public limit after numerical cleanup.
    s = float(np.sum(design[:, 0]))
    if s > max_total > 0:
        scale = max_total / s
        design[:, 0] *= scale
        design[:, 0] = np.clip(design[:, 0], depth_lo, depth_hi)

    return design

import math

BASES = "ACGU"


def design_rna(problem):
    n = int(problem["length"])
    pairs = _parse_pairs(problem["target_structure"])
    pairset = set(pairs)
    best_s, best_sc = None, -1e300

    modes = 30 if n <= 180 else 18
    for mode in range(modes):
        seq = _make_candidate(problem, pairs, mode)
        seq = _repair(seq, problem, pairs)
        if n <= 155 and mode < 10:
            seq = _refine_unpaired(seq, problem, pairs, pairset, 1)
        if n <= 135 and mode < 8:
            seq = _refine_pairs(seq, problem, pairs, pairset, 1)
        s = "".join(seq)
        sc = _score(s, problem, pairs, pairset)
        if sc > best_sc:
            best_sc, best_s = sc, s

    if best_s is None:
        best_s = ("ACGU" * ((n + 3) // 4))[:n]

    final = _repair(list(best_s), problem, pairs)
    return {"sequence": "".join(final)}


def _parse_pairs(db):
    st, pairs = [], []
    for i, c in enumerate(db):
        if c == "(":
            st.append(i)
        elif c == ")" and st:
            pairs.append((st.pop(), i))
    pairs.sort()
    return pairs


def _gc_count(seq):
    return sum(1 for b in seq if b in "GC")


def _forbidden_ok(s, motifs):
    return all(m not in s for m in motifs)


def _stack_bonus(p1, p2):
    if p1 in ("GC", "CG") and p2 in ("GC", "CG"):
        return -0.75
    if p1 in ("GU", "UG") or p2 in ("GU", "UG"):
        return -0.25
    return -0.45


def _pair_options(pe):
    opts = [(float(e), p) for p, e in pe.items()
            if isinstance(p, str) and len(p) == 2 and p[0] in BASES and p[1] in BASES]
    opts.sort()
    return opts or [(-3.0, "GC"), (-2.8, "CG"), (-2.0, "AU"), (-2.0, "UA"), (-1.0, "GU"), (-1.0, "UG")]


def _target_energy(seq, pairs, pairset, pe, loop):
    e = 0.0
    for i, j in pairs:
        p = seq[i] + seq[j]
        if p not in pe:
            return 1e100
        e += float(pe[p])
        if (i + 1, j - 1) in pairset:
            p2 = seq[i + 1] + seq[j - 1]
            if p2 not in pe:
                return 1e100
            e += _stack_bonus(p, p2)
        else:
            e += float(loop)
    return e


def _make_candidate(problem, pairs, mode):
    n = int(problem["length"])
    pe = problem["pair_energies"]
    fixed = {int(i): str(b) for i, b in problem.get("fixed_bases", [])}
    paired = {x for p in pairs for x in p}
    seq = ["A"] * n
    pats = ("ACACUCA", "CAAUACA", "AACCUAA", "CUAACUA", "ACUUCAA", "UCAACAA",
            "CCAUAUA", "AAUCAAC", "ACAAUCU", "UUAACAA", "CACAUUA", "AUAACCU")
    pat = pats[mode % len(pats)]
    shift = mode // len(pats)
    for i in range(n):
        if i not in paired:
            seq[i] = pat[(i + shift) % len(pat)]

    opts = _pair_options(pe)
    # Helix-aware alternation: stacked GC/CG is often best, but pure GC can create off-targets.
    for idx, (i, j) in enumerate(pairs):
        lf, rf = fixed.get(i), fixed.get(j)
        cand = []
        for e, p in opts:
            if lf is not None and p[0] != lf:
                continue
            if rf is not None and p[1] != rf:
                continue
            gc = (p[0] in "GC") + (p[1] in "GC")
            wob = p in ("GU", "UG")
            m = mode % 15
            if m == 0:
                pref = (0 if p in ("GC", "CG") else 2, e)
            elif m == 1:
                pref = (0 if p == ("GC" if idx % 2 == 0 else "CG") else 1, e)
            elif m == 2:
                pref = (abs(gc - 1), e)
            elif m == 3:
                pref = (gc, e)
            elif m == 4:
                pref = (-gc, e)
            elif m == 5:
                pref = (wob, e)
            elif m == 6:
                pref = (0 if p in ("AU", "UA") else 1, e)
            elif m == 7:
                pref = (0 if p in ("CG", "GC") else 1, p != "CG", e)
            elif m == 8:
                pref = (0 if p in ("GC", "AU") else 1, e)
            elif m == 9:
                pref = (0 if p in ("CG", "UA") else 1, e)
            elif m == 10:
                pref = (idx % 3 != 0 and gc == 2, e)
            elif m == 11:
                pref = (0 if p in ("GC", "UA", "AU") else 1, e)
            elif m == 12:
                pref = (0 if p in ("CG", "AU", "UA") else 1, e)
            elif m == 13:
                pref = (abs((idx + mode) % 4 - gc), e)
            else:
                pref = (e, abs(gc - 1))
            cand.append((pref, p))
        if cand:
            cand.sort()
            p = cand[0][1]
            seq[i], seq[j] = p[0], p[1]
        else:
            seq[i], seq[j] = fixed.get(i, "G"), fixed.get(j, "C")

    for i, b in fixed.items():
        if 0 <= i < n:
            seq[i] = b
    return seq


def _repair(seq, problem, pairs):
    n = len(seq)
    fixed = {int(i): str(b) for i, b in problem.get("fixed_bases", [])}
    motifs = list(problem.get("forbidden_motifs", []))
    lo, hi = problem.get("gc_fraction", (0.0, 1.0))
    lo_cnt = int(math.ceil(float(lo) * n - 1e-12))
    hi_cnt = int(math.floor(float(hi) * n + 1e-12))
    partner = {}
    for i, j in pairs:
        partner[i] = j
        partner[j] = i

    for i, b in fixed.items():
        if 0 <= i < n:
            seq[i] = b

    for _ in range(6 * n + 40):
        gc = _gc_count(seq)
        if lo_cnt <= gc <= hi_cnt:
            break
        need = gc < lo_cnt
        changed = False
        order = list(range(n))
        order.sort(key=lambda x: (x in fixed, x in partner, x))
        for i in order:
            if i in fixed:
                continue
            old = seq[i]
            if need and old not in "GC":
                for b in "GC":
                    seq[i] = b
                    changed = True
                    break
            elif (not need) and old in "GC":
                for b in "AU":
                    seq[i] = b
                    changed = True
                    break
            if changed:
                break
        if not changed:
            break

    for _ in range(14 * n + 100):
        s = "".join(seq)
        bad = None
        for m in motifs:
            k = s.find(m)
            if k >= 0:
                bad = (k, m)
                break
        if bad is None:
            break
        k, m = bad
        done = False
        pos = list(range(k, k + len(m)))
        pos.sort(key=lambda x: (x in fixed, x in partner, -x))
        for p in pos:
            if p in fixed or p < 0 or p >= n:
                continue
            old = seq[p]
            # Prefer A/U changes for motif breaking unless GC is needed.
            for b in "AUCG":
                if b == old:
                    continue
                ngc = _gc_count(seq) - (old in "GC") + (b in "GC")
                if lo_cnt <= ngc <= hi_cnt:
                    seq[p] = b
                    if _forbidden_ok("".join(seq), motifs):
                        done = True
                        break
                    seq[p] = old
            if done:
                break
        if not done:
            break

    for i, b in fixed.items():
        if 0 <= i < n:
            seq[i] = b
    return seq


def _valid_penalty(s, problem):
    n = int(problem["length"])
    if len(s) != n or any(c not in BASES for c in s):
        return -100000.0
    pen = 0.0
    lo, hi = problem.get("gc_fraction", (0.0, 1.0))
    f = _gc_count(s) / max(1, n)
    if not (float(lo) - 1e-12 <= f <= float(hi) + 1e-12):
        pen -= 10000.0
    if not _forbidden_ok(s, list(problem.get("forbidden_motifs", []))):
        pen -= 10000.0
    for i, b in problem.get("fixed_bases", []):
        if s[int(i)] != str(b):
            pen -= 10000.0
    return pen


def _partition_logz(seq, min_h, pe, loop, rt):
    n = len(seq)
    if n == 0:
        return 0.0
    q = [[1.0] * n for _ in range(n)]
    qb = [[0.0] * n for _ in range(n)]

    def Q(i, j):
        return 1.0 if i > j else q[i][j]

    for span in range(1, n):
        for i in range(n - span):
            j = i + span
            p = seq[i] + seq[j]
            if j - i > min_h and p in pe:
                wl = math.exp(-(float(pe[p]) + float(loop)) / rt)
                val = wl * Q(i + 1, j - 1)
                if i + 1 < j - 1 and (j - i - 2) > min_h:
                    p2 = seq[i + 1] + seq[j - 1]
                    ib = qb[i + 1][j - 1]
                    if ib and p2 in pe:
                        ws = math.exp(-(float(pe[p]) + _stack_bonus(p, p2)) / rt)
                        val += (ws - wl) * ib
                qb[i][j] = max(0.0, val)
            total = Q(i + 1, j)
            for k in range(i + min_h + 1, j + 1):
                b = qb[i][k]
                if b:
                    total += b * Q(k + 1, j)
            if not math.isfinite(total):
                return 1e100
            q[i][j] = total
    z = q[0][n - 1]
    return math.log(z) if z > 0 and math.isfinite(z) else 1e100


def _mfe_pairs(seq, min_h, pe, loop):
    n = len(seq)
    if n == 0:
        return set(), 0.0
    INF = 1e18
    dp = [[0.0] * n for _ in range(n)]
    pp = [[INF] * n for _ in range(n)]
    for span in range(1, n):
        for i in range(n - span):
            j = i + span
            best = dp[i + 1][j] if i + 1 <= j else 0.0
            if dp[i][j - 1] < best:
                best = dp[i][j - 1]
            for k in range(i, j):
                v = dp[i][k] + dp[k + 1][j]
                if v < best:
                    best = v
            p = seq[i] + seq[j]
            if j - i > min_h and p in pe:
                val = float(pe[p]) + float(loop) + (dp[i + 1][j - 1] if i + 1 <= j - 1 else 0.0)
                if i + 1 < j - 1 and (j - i - 2) > min_h:
                    p2 = seq[i + 1] + seq[j - 1]
                    if p2 in pe and pp[i + 1][j - 1] < INF / 2:
                        val = min(val, float(pe[p]) + _stack_bonus(p, p2) + pp[i + 1][j - 1])
                pp[i][j] = val
                if val < best:
                    best = val
            dp[i][j] = best

    res = set()

    def tb_dp(i, j):
        if i >= j:
            return
        cur = dp[i][j]
        if i + 1 <= j and abs(cur - dp[i + 1][j]) < 1e-8:
            tb_dp(i + 1, j)
            return
        if i <= j - 1 and abs(cur - dp[i][j - 1]) < 1e-8:
            tb_dp(i, j - 1)
            return
        if pp[i][j] < INF / 2 and abs(cur - pp[i][j]) < 1e-8:
            tb_pp(i, j)
            return
        for k in range(i, j):
            if abs(cur - (dp[i][k] + dp[k + 1][j])) < 1e-8:
                tb_dp(i, k)
                tb_dp(k + 1, j)
                return

    def tb_pp(i, j):
        res.add((i, j))
        p = seq[i] + seq[j]
        non = float(pe[p]) + float(loop) + (dp[i + 1][j - 1] if i + 1 <= j - 1 else 0.0)
        if abs(pp[i][j] - non) < 1e-8:
            tb_dp(i + 1, j - 1)
        elif i + 1 < j - 1:
            tb_pp(i + 1, j - 1)

    tb_dp(0, n - 1)
    return res, dp[0][n - 1]


def _f1(pred, targ):
    if not pred and not targ:
        return 1.0
    if not pred or not targ:
        return 0.0
    return 2.0 * len(pred & targ) / (len(pred) + len(targ))


def _offtarget(s, pairs, min_h, pe, limit=175):
    n = len(s)
    if n > limit:
        return 0.0
    pairset = set(pairs)
    paired = {x for p in pairs for x in p}
    off = 0.0
    for i in range(n):
        wi = 0.50 if i not in paired else 1.0
        bi = s[i]
        for j in range(i + min_h + 1, n):
            if (i, j) in pairset:
                continue
            e = pe.get(bi + s[j])
            if e is not None and float(e) < 0:
                wj = 0.50 if j not in paired else 1.0
                off += wi * wj * (-float(e))
    return off


def _score(s, problem, pairs, pairset):
    n = len(s)
    pe = problem["pair_energies"]
    loop = float(problem["loop_initiation_kcal"])
    min_h = int(problem["min_hairpin"])
    rt = float(problem["gas_constant_kcal"]) * float(problem["temperature_kelvin"])

    pen = _valid_penalty(s, problem)
    compat = sum(1 for i, j in pairs if s[i] + s[j] in pe) / max(1, len(pairs))
    te = _target_energy(s, pairs, pairset, pe, loop)
    logp = -1e6
    if te < 1e90 and n <= 235:
        try:
            logz = _partition_logz(s, min_h, pe, loop, rt)
            logp = max(-1e6, min(0.0, -te / rt - logz))
        except Exception:
            logp = -1e6

    if n <= 195:
        pred, mfe = _mfe_pairs(s, min_h, pe, loop)
        f = _f1(pred, pairset)
    else:
        mfe, f = 0.0, compat

    off = _offtarget(s, pairs, min_h, pe)
    # Slightly increased exact-log-prob weight plus MFE protection.  This tends to
    # select less over-stabilized distractor-rich sequences than compatibility-only choices.
    return pen + 13.0 * f + 4.5 * compat + 3.15 * logp - 0.034 * off - 0.035 * max(0.0, te - mfe if n <= 195 else 0.0)


def _refine_unpaired(seq, problem, pairs, pairset, rounds=1):
    n = len(seq)
    fixed = {int(i): str(b) for i, b in problem.get("fixed_bases", [])}
    paired = {x for p in pairs for x in p}
    lo, hi = problem.get("gc_fraction", (0.0, 1.0))
    lo_cnt = int(math.ceil(float(lo) * n - 1e-12))
    hi_cnt = int(math.floor(float(hi) * n + 1e-12))
    best = "".join(seq)
    best_sc = _score(best, problem, pairs, pairset)
    mutable = [i for i in range(n) if i not in fixed and i not in paired]

    if len(mutable) > 38:
        min_h = int(problem["min_hairpin"])
        pe = problem["pair_energies"]
        burden = []
        for i in mutable:
            val = 0.0
            for j in range(n):
                if abs(i - j) > min_h and (min(i, j), max(i, j)) not in pairset:
                    e = pe.get(best[i] + best[j]) if i < j else pe.get(best[j] + best[i])
                    if e is not None and float(e) < 0:
                        val += -float(e)
            burden.append((-val, i))
        burden.sort()
        mutable = [i for _, i in burden[:38]]

    cur = list(best)
    for _ in range(rounds):
        improved = False
        for i in mutable:
            old = cur[i]
            for b in BASES:
                if b == old:
                    continue
                ngc = _gc_count(cur) - (old in "GC") + (b in "GC")
                if not (lo_cnt <= ngc <= hi_cnt):
                    continue
                cur[i] = b
                cand = _repair(cur[:], problem, pairs)
                s = "".join(cand)
                sc = _score(s, problem, pairs, pairset)
                if sc > best_sc + 1e-9:
                    best, best_sc = s, sc
                    cur = list(s)
                    improved = True
                    old = cur[i]
                else:
                    cur[i] = old
            cur = list(best)
        if not improved:
            break
    return list(best)


def _refine_pairs(seq, problem, pairs, pairset, rounds=1):
    """Exact-score-guided target-pair mutation.

    The parent program generated many helix phases but never locally revisited paired
    positions.  A single deterministic pass over the most influential pairs often fixes
    GC-bound repairs, bad fixed-base choices, or excessive off-target stabilization while
    preserving target compatibility.
    """
    n = len(seq)
    fixed = {int(i): str(b) for i, b in problem.get("fixed_bases", [])}
    pe = problem["pair_energies"]
    opts = [p for _, p in _pair_options(pe)]
    lo, hi = problem.get("gc_fraction", (0.0, 1.0))
    lo_cnt = int(math.ceil(float(lo) * n - 1e-12))
    hi_cnt = int(math.floor(float(hi) * n + 1e-12))

    best = "".join(seq)
    best_sc = _score(best, problem, pairs, pairset)

    order = []
    for idx, (i, j) in enumerate(pairs):
        depth_bonus = 0
        if (i + 1, j - 1) in pairset:
            depth_bonus += 1
        if (i - 1, j + 1) in pairset:
            depth_bonus += 1
        order.append((-depth_bonus, idx, i, j))
    order.sort()
    if len(order) > 32:
        order = order[:32]

    cur = list(best)
    for _ in range(rounds):
        improved = False
        for _, _, i, j in order:
            if i in fixed and j in fixed:
                continue
            oldi, oldj = cur[i], cur[j]
            for p in opts:
                if i in fixed and p[0] != fixed[i]:
                    continue
                if j in fixed and p[1] != fixed[j]:
                    continue
                if p[0] == oldi and p[1] == oldj:
                    continue
                ngc = _gc_count(cur) - (oldi in "GC") - (oldj in "GC") + (p[0] in "GC") + (p[1] in "GC")
                if not (lo_cnt <= ngc <= hi_cnt):
                    continue
                cur[i], cur[j] = p[0], p[1]
                cand = _repair(cur[:], problem, pairs)
                # Do not accept repairs that destroyed this target pair.
                if cand[i] + cand[j] not in pe:
                    cur[i], cur[j] = oldi, oldj
                    continue
                s = "".join(cand)
                sc = _score(s, problem, pairs, pairset)
                if sc > best_sc + 1e-9:
                    best, best_sc = s, sc
                    cur = list(s)
                    improved = True
                    oldi, oldj = cur[i], cur[j]
                else:
                    cur[i], cur[j] = oldi, oldj
            cur = list(best)
        if not improved:
            break
    return list(best)

import numpy as np
from scipy.optimize import minimize


def design_truss(nodes, members, fixed_dofs, load_cases, youngs_modulus, density,
                 tension_allowable, compression_allowable, displacement_limit,
                 area_min, area_max, inertia_coefficient):
    nodes = np.asarray(nodes, dtype=float)
    members = np.asarray(members, dtype=int)
    fixed_dofs = np.asarray(fixed_dofs, dtype=int)
    load_cases = np.asarray(load_cases, dtype=float)

    n_nodes = nodes.shape[0]
    n_members = members.shape[0]
    ndof = 2 * n_nodes

    if n_members == 0:
        return np.zeros(0, dtype=float)

    area_min = float(area_min)
    area_max = float(area_max)
    E0 = float(youngs_modulus)
    rho = float(density)
    t_allow0 = float(tension_allowable)
    c_allow0 = float(compression_allowable)
    disp_lim = float(displacement_limit)
    inert_coeff = float(inertia_coefficient)

    if (not np.isfinite(area_min)) or (not np.isfinite(area_max)) or area_max < area_min:
        return np.ones(n_members, dtype=float)

    i_nodes = members[:, 0]
    j_nodes = members[:, 1]
    xy_i = nodes[i_nodes]
    xy_j = nodes[j_nodes]
    dxy = xy_j - xy_i
    lengths = np.linalg.norm(dxy, axis=1)
    lengths = np.maximum(lengths, 1e-12)
    c = dxy[:, 0] / lengths
    s = dxy[:, 1] / lengths

    dofs = np.empty((n_members, 4), dtype=int)
    dofs[:, 0] = 2 * i_nodes
    dofs[:, 1] = 2 * i_nodes + 1
    dofs[:, 2] = 2 * j_nodes
    dofs[:, 3] = 2 * j_nodes + 1

    bvec = np.column_stack((-c, -s, c, s))
    avec = np.column_stack((c, s, -c, -s))
    kdirs = np.empty((n_members, 4, 4), dtype=float)
    for m in range(n_members):
        kdirs[m] = np.outer(avec[m], avec[m]) / lengths[m]

    all_dofs = np.arange(ndof)
    fixed_mask = np.zeros(ndof, dtype=bool)
    fixed_dofs = fixed_dofs[(fixed_dofs >= 0) & (fixed_dofs < ndof)]
    fixed_mask[fixed_dofs] = True
    free_dofs = all_dofs[~fixed_mask]

    weights = rho * lengths
    scale = max(area_max - area_min, 1e-30)

    def assemble_solve(areas_eff, E, loads):
        K = np.zeros((ndof, ndof), dtype=float)
        coeff = E * areas_eff
        for mm in range(n_members):
            dm = dofs[mm]
            K[np.ix_(dm, dm)] += coeff[mm] * kdirs[mm]

        u = np.zeros(ndof, dtype=float)
        if free_dofs.size:
            Kff = K[np.ix_(free_dofs, free_dofs)]
            ff = loads.reshape(ndof)[free_dofs]
            try:
                u_free = np.linalg.solve(Kff, ff)
            except Exception:
                try:
                    tr = float(np.trace(Kff)) / max(1, Kff.shape[0])
                    reg = 1e-9 * (abs(tr) + 1.0)
                    u_free = np.linalg.lstsq(Kff + np.eye(Kff.shape[0]) * reg, ff, rcond=None)[0]
                except Exception:
                    return None
            if not np.all(np.isfinite(u_free)):
                return None
            u[free_dofs] = u_free
        return u

    def margins_for(areas, load_fac=1.0, E_fac=1.0, allow_fac=1.0, area_fac=1.0):
        areas_eff = np.asarray(areas, dtype=float) * area_fac
        if np.any(areas_eff <= 0.0) or not np.all(np.isfinite(areas_eff)):
            return np.array([-1e9], dtype=float)

        E = E0 * E_fac
        t_allow = t_allow0 * allow_fac
        c_allow = c_allow0 * allow_fac
        vals = []

        pe = (np.pi ** 2) * E * inert_coeff * areas_eff ** 2 / (lengths ** 2)

        for lc in load_cases:
            u = assemble_solve(areas_eff, E, lc * load_fac)
            if u is None:
                return np.array([-1e9], dtype=float)

            if free_dofs.size:
                vals.extend((disp_lim - np.abs(u[free_dofs])) / max(disp_lim, 1e-30))

            ue = u[dofs]
            delta = np.einsum("ij,ij->i", ue, bvec)
            stress = E * delta / lengths
            force = stress * areas_eff

            vals.extend((t_allow - stress) / max(t_allow, 1e-30))
            vals.extend((c_allow + stress) / max(c_allow, 1e-30))
            vals.extend((pe + force) / np.maximum(pe, 1e-30))

        if len(vals) == 0:
            return np.array([1.0], dtype=float)
        vals = np.asarray(vals, dtype=float)
        vals[~np.isfinite(vals)] = -1e9
        return vals

    def min_margin(areas, lf=1.0, ef=1.0, af=1.0, arf=1.0):
        return float(np.min(margins_for(areas, lf, ef, af, arf)))

    def feasible_nominal(areas, tol=-2e-7):
        return min_margin(areas) >= tol

    max_areas = np.full(n_members, area_max, dtype=float)
    robust_possible = min_margin(max_areas, 1.12, 0.92, 0.92, 0.95) >= -1e-7
    if robust_possible:
        lf, ef, af, arf = 1.12, 0.92, 0.92, 0.95
    else:
        lf, ef, af, arf = 1.0, 1.0, 1.0, 1.0

    def target_feasible(a, tol=-1e-7):
        return min_margin(a, lf, ef, af, arf) >= tol

    def unpack(x):
        return area_min + scale * np.asarray(x, dtype=float)

    def pack(a):
        return np.clip((np.asarray(a, dtype=float) - area_min) / scale, 0.0, 1.0)

    def objective_x(x):
        return float(np.dot(weights, unpack(x)))

    def objective_a(a):
        return float(np.dot(weights, a))

    def constraint_fun(x):
        return margins_for(unpack(x), lf, ef, af, arf)

    bounds = [(0.0, 1.0)] * n_members

    best_a = max_areas.copy()
    best_obj = objective_a(best_a)

    def consider(a, robust_check=True):
        nonlocal best_a, best_obj
        a = np.asarray(a, dtype=float)
        if a.shape != (n_members,) or not np.all(np.isfinite(a)):
            return
        if np.any(a < area_min - 1e-10) or np.any(a > area_max + 1e-10):
            return
        ok = target_feasible(a, -5e-7) if robust_check else feasible_nominal(a, -5e-7)
        if ok:
            obj = objective_a(a)
            if obj < best_obj:
                best_a = np.clip(a, area_min, area_max)
                best_obj = obj

    demand_force = np.zeros(n_members, dtype=float)
    for lc in load_cases:
        u = assemble_solve(max_areas, E0, lc)
        if u is not None:
            delta = np.einsum("ij,ij->i", u[dofs], bvec)
            stress = E0 * delta / lengths
            force = stress * max_areas
            demand_force = np.maximum(demand_force,
                                      np.maximum(force / max(t_allow0, 1e-30),
                                                 -force / max(c_allow0, 1e-30)))
    buck_a = np.sqrt(np.maximum(0.0, (-demand_force * max(c_allow0, 1e-30)) *
                                lengths ** 2 / max((np.pi ** 2) * E0 * inert_coeff, 1e-30)))
    est = np.maximum(area_min, np.maximum(demand_force, buck_a))
    est = np.clip(est * (1.25 if robust_possible else 1.08), area_min, area_max)

    starts = [
        np.ones(n_members, dtype=float),
        pack(est),
        np.full(n_members, 0.65, dtype=float),
        np.full(n_members, 0.35, dtype=float),
    ]

    lo, hi = 0.0, 1.0
    for _ in range(28):
        mid = 0.5 * (lo + hi)
        aa = area_min + (area_max - area_min) * mid * np.ones(n_members)
        if target_feasible(aa, -2e-7):
            hi = mid
        else:
            lo = mid
    starts.append(np.full(n_members, hi, dtype=float))

    for x0 in starts:
        x0 = np.clip(np.asarray(x0, dtype=float), 0.0, 1.0)

        def cb(xk):
            consider(unpack(np.clip(xk, 0.0, 1.0)), robust_check=True)

        try:
            res = minimize(objective_x, x0, method="SLSQP", bounds=bounds,
                           constraints=({"type": "ineq", "fun": constraint_fun},),
                           options={"maxiter": 170, "ftol": 3e-8, "disp": False},
                           callback=cb)
            if res is not None and hasattr(res, "x"):
                consider(unpack(np.clip(res.x, 0.0, 1.0)), robust_check=True)
        except Exception:
            pass

    if not target_feasible(best_a, -5e-7):
        best_a = max_areas.copy()

    areas = best_a.copy()

    def group_shrink(areas_in, tol_feas):
        """Deterministic subset scaling polish.  This can improve cases where no single
        member can be reduced much alone, but a group can move down together."""
        areas_out = areas_in.copy()
        slack = np.maximum(areas_out - area_min, 0.0)
        if np.all(slack <= 0):
            return areas_out

        idx_weight = np.argsort(-(weights * slack))
        idx_area = np.argsort(-slack)
        idx_len = np.argsort(-lengths)

        groups = []
        groups.append(np.arange(n_members))
        for frac in (0.75, 0.50, 0.33, 0.20):
            k = max(1, int(np.ceil(frac * n_members)))
            groups.append(idx_weight[:k])
            groups.append(idx_area[:k])
            groups.append(idx_len[:k])

        if n_members >= 6:
            medx = np.median((xy_i[:, 0] + xy_j[:, 0]) * 0.5)
            medy = np.median((xy_i[:, 1] + xy_j[:, 1]) * 0.5)
            mx = (xy_i[:, 0] + xy_j[:, 0]) * 0.5
            my = (xy_i[:, 1] + xy_j[:, 1]) * 0.5
            for mask in (mx <= medx, mx > medx, my <= medy, my > medy,
                         np.abs(c) >= np.abs(s), np.abs(c) < np.abs(s)):
                g = np.nonzero(mask)[0]
                if g.size:
                    groups.append(g)

        for g in groups:
            g = np.asarray(g, dtype=int)
            if g.size == 0:
                continue
            base = areas_out.copy()
            if np.sum(weights[g] * np.maximum(base[g] - area_min, 0.0)) <= 1e-14:
                continue
            lo, hi = 0.0, 1.0
            test = base.copy()
            test[g] = area_min
            if target_feasible(test, tol_feas):
                areas_out = test
                continue
            for _ in range(24):
                mid = 0.5 * (lo + hi)
                test = base.copy()
                test[g] = area_min + mid * (base[g] - area_min)
                if target_feasible(test, tol_feas):
                    hi = mid
                else:
                    lo = mid
            test = base.copy()
            test[g] = area_min + min(1.0, hi * (1.0 + 3e-8) + 1e-10) * (base[g] - area_min)
            if objective_a(test) < objective_a(areas_out) and target_feasible(test, tol_feas):
                areas_out = test
        return areas_out

    tol_feas = 1e-6 if robust_possible else 2e-7
    areas = group_shrink(areas, tol_feas)

    order = np.argsort(-(weights * np.maximum(areas - area_min, 0.0)))
    passes = 4 if n_members <= 80 else 2

    for pp in range(passes):
        improved = False
        for mm in order:
            old = areas[mm]
            if old <= area_min * (1.0 + 1e-10) + 1e-12:
                continue
            lo = area_min
            hi = old
            test = areas.copy()
            test[mm] = lo
            if target_feasible(test, tol_feas):
                areas[mm] = lo
                improved = True
                continue
            for __ in range(23):
                mid = 0.5 * (lo + hi)
                test[mm] = mid
                if target_feasible(test, tol_feas):
                    hi = mid
                else:
                    lo = mid
            newv = min(old, hi * (1.0 + 2e-8) + 1e-10)
            if newv < old - max(1e-9, 1e-7 * scale):
                areas[mm] = newv
                improved = True

        # A second subset shrink after coordinate moves often removes common-mode slack
        # introduced by conservative SLSQP convergence tolerances.
        if pp < 2:
            new_areas = group_shrink(areas, tol_feas)
            if objective_a(new_areas) < objective_a(areas) - 1e-12:
                areas = new_areas
                improved = True

        if not improved:
            break
        order = np.argsort(-(weights * np.maximum(areas - area_min, 0.0)))

    if not robust_possible:
        for _ in range(2):
            areas = group_shrink(areas, 2e-7)
            for mm in np.argsort(-(weights * np.maximum(areas - area_min, 0.0))):
                old = areas[mm]
                lo = area_min
                hi = old
                test = areas.copy()
                test[mm] = lo
                if feasible_nominal(test, 2e-7):
                    areas[mm] = lo
                    continue
                for __ in range(21):
                    mid = 0.5 * (lo + hi)
                    test[mm] = mid
                    if feasible_nominal(test, 2e-7):
                        hi = mid
                    else:
                        lo = mid
                areas[mm] = min(old, hi * (1.0 + 5e-8) + 1e-10)

    if robust_possible:
        for _ in range(10):
            if target_feasible(areas, 2e-6):
                break
            m = min_margin(areas, lf, ef, af, arf)
            fac = min(1.12, 1.0 + max(0.002, -m * 0.35))
            areas = np.minimum(area_max, area_min + (areas - area_min) * fac + 1e-10)
        if not target_feasible(areas, -2e-6):
            areas = best_a.copy()

    if not feasible_nominal(areas, -2e-7):
        for _ in range(12):
            if feasible_nominal(areas, 2e-6):
                break
            m = min_margin(areas)
            fac = min(1.15, 1.0 + max(0.003, -m * 0.4))
            areas = np.minimum(area_max, area_min + (areas - area_min) * fac + 1e-10)
        if not feasible_nominal(areas, -2e-7):
            areas = max_areas.copy()

    areas = np.asarray(areas, dtype=float)
    areas[~np.isfinite(areas)] = area_max
    areas = np.minimum(np.maximum(areas, area_min), area_max)

    return areas
